$('mwForm').onsubmit=async e=>{e.preventDefault();if(controller)return;let token;try{const c=config();token=revision;controller=new AbortController();$('status').textContent='กำลังเตรียมแนวลิงก์และอ่าน DEM…';$('calculate').disabled=true;$('cancel').disabled=false;for(const e of $('mwForm').querySelectorAll('input,select,textarea,button'))e.disabled=true;$('example').disabled=true;$('print').disabled=$('download').disabled=$('csv').disabled=true;const key=JSON.stringify([c.a.lat,c.a.lon,c.b.lat,c.b.lon,c.freq,c.step,c.obstacles]);let t=terrainCache;if(key!==terrainKey||!t){t=await MWDEM.load(c,controller.signal,v=>$('status').textContent=v);if(controller.signal.aborted)return;terrainCache=t;terrainKey=key}if(token!==revision)return;resolveHeights(c,t);if(t.missing)throw Error('DEM ขาด '+t.missing+' ตัวอย่าง ไม่สรุปว่าทางโล่ง กรุณาลองใหม่หรือเปลี่ยนเส้นทาง');result=MWMath.analyze(c,t);lastConfig=structuredClone(c);lastConfig.terrain={source:t.source,pixelM:t.pixelM,step:t.step,width:t.width,tiles:t.tiles};lastConfig.calculatedAt=new Date().toISOString();$('results').hidden=false;render();$('print').disabled=$('download').disabled=$('csv').disabled=false;$('status').textContent='คำนวณสำเร็จ · '+t.rows.length.toLocaleString()+' จุดตามแนว × 17 จุดขวางทาง · '+t.source;dirtySaveOnly();globalThis.MWDishUI?.onCalculated(lastConfig,result);globalThis.MWXPDUI?.onCalculated(lastConfig,result)}catch(err){$('status').textContent=err.name==='AbortError'?'หยุดคำนวณแล้ว':'คำนวณไม่สำเร็จ · '+err.message}finally{controller=null;$('calculate').disabled=false;$('cancel').disabled=true;$('example').disabled=false;for(const e of $('mwForm').querySelectorAll('input,select,textarea,button'))e.disabled=false}};
